from PIL import Image
import torchvision.transforms as T
import torchvision.transforms.functional as TF
import torch.nn.functional as F
import glob, os, math
import matplotlib.pyplot as plt

# Reuse 'classes', 'device', and 'model' from previous cells.
# If running standalone, make sure the model is defined/loaded and set to eval().

# --- Transforms ---
normalize_05 = T.Normalize((0.5,0.5,0.5), (0.5,0.5,0.5))

simple_32 = T.Compose([
    T.Resize((32,32)),
    T.ToTensor(),
    normalize_05,
])

keep_aspect_32 = T.Compose([
    T.Resize(36),          # scale so min side >= 36
    T.CenterCrop(32),      # crop to 32x32 (keeps aspect better)
    T.ToTensor(),
    normalize_05,
])

def load_image(path):
    img = Image.open(path).convert('RGB')
    return img

def preprocess(img, mode='keep_aspect'):
    if mode == 'simple':
        return simple_32(img)
    else:
        return keep_aspect_32(img)

@torch.no_grad()
def predict_image(model, img_tensor, classes):
    model.eval()
    img_tensor = img_tensor.unsqueeze(0).to(device)  # (1,3,32,32)
    logits = model(img_tensor)
    probs = F.softmax(logits, dim=1).squeeze(0).cpu().numpy()
    top_idx = int(probs.argmax())
    return classes[top_idx], float(probs[top_idx]), probs

def show_with_title(img, title):
    plt.imshow(img); plt.title(title); plt.axis('off'); plt.show()

import requests, io
from PIL import Image

def load_image_from_url(url, timeout=10):
    headers = {'User-Agent': 'Mozilla/5.0'}
    r = requests.get(url, headers=headers, timeout=timeout)
    r.raise_for_status()
    img = Image.open(io.BytesIO(r.content)).convert('RGB')
    return img

