if input_url:
    try:
        img = load_image_from_url(input_url)
        mode = 'keep_aspect'  # 'simple' or 'keep_aspect'
        x = preprocess(img, mode=mode)
        pred, conf, _ = predict_image(model, x, classes)
        show_with_title(img, f'Pred: {pred} (conf {conf:.2f}) | mode={mode}')
    except Exception as e:
        print('Failed to load or predict:', e)
